"""Build a measured event player from a native run; no invented actor states."""
import argparse,json,html
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('run');p.add_argument('out');a=p.parse_args();run=Path(a.run)
summary=json.loads((run/'summary.json').read_text());manifest=json.loads((run/'manifest.json').read_text())
cases=[]
for f in sorted(run.glob('case-*.json'),key=lambda x:int(x.stem.split('-')[1])):
 i=f.stem.split('-')[1];c=json.loads(f.read_text());events=[json.loads(x) for x in (run/f'events-{i}.jsonl').read_text().splitlines()]
 cases.append({'label':c['case_id']+' / '+c['world'],'brief':c['brief'],'events':events})
data=json.dumps({'summary':summary,'manifest':manifest,'cases':cases}).replace('<','\\u003c')
template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Measured procurement replay</title><style>body{font:16px/1.5 system-ui;background:#101c27;color:#e1edf2;max-width:1160px;margin:32px auto;padding:20px}h1{font-size:42px;line-height:1.1}p{color:#b1c8d2}button,select{background:#203642;color:#e1edf2;border:1px solid #77949f;padding:10px;border-radius:6px}input{width:100%}section{background:#162b37;padding:22px;border-radius:10px;margin:20px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 ui-monospace}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #48606b;text-align:left}.good{color:#74dfc7}.bad{color:#ffaa91}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style><body><p class="good">RECORDED MODEL RESPONSES · SYNTHETIC PROCUREMENT · SHARED TEAM PREFIX</p><h1>How to win agents<br>and influence swarms</h1><p id="summary"></p><select id="case" aria-label="Recorded case"></select> <button id="play">Play</button> <button id="reset">Reset</button><p id="position"></p><input id="scrub" aria-label="Recorded event" type="range" min="0" value="0"><div class="grid"><section><h2>Observed event</h2><p id="eventType"></p><pre id="event"></pre></section><section><h2>Decisions so far</h2><table><thead><tr><th>Workflow</th><th>Choice</th><th>Assessment</th></tr></thead><tbody id="decisions"></tbody></table><p>No reply yet means pending. Invalid output is shown explicitly. Evaluation appears only after the recorded terminal event.</p></section></div><section><h2>Buyer brief</h2><pre id="brief"></pre></section><p>Logical event order is replayed at a fixed playback rate. Recorded elapsed seconds remain visible; playback speed is not original wall time. Team chairs share the same eight-call prefix. This pilot does not establish general robustness.</p><script>const D=__DATA__,$=id=>document.getElementById(id);let timer=null;D.cases.forEach((c,i)=>$('case').add(new Option(c.label,i)));$('summary').textContent=`${D.summary.stage}: ${D.summary.terminal}/${D.summary.planned} terminal, ${D.summary.valid} valid, ${D.summary.acceptable} acceptable; ${D.summary.calls} API attempts; reported $${D.summary.actual_usd.toFixed(4)}.`;function stop(){clearInterval(timer);timer=null;$('play').textContent='Play'}function render(){let c=D.cases[+$('case').value],i=+$('scrub').value,e=c.events[i];$('scrub').max=c.events.length-1;$('position').textContent=`Event ${i+1}/${c.events.length} • recorded elapsed ${e.elapsed_seconds.toFixed(1)}s`;$('eventType').textContent=e.kind+(e.phase?' / '+e.phase:'');$('event').textContent=JSON.stringify(e,null,2);$('brief').textContent=JSON.stringify(c.brief,null,2);$('decisions').replaceChildren();for(let arm of ['team_ballots','team_evidence','solo']){let r=c.events.slice(0,i+1).filter(x=>x.kind==='terminal'&&x.outcome.arm===arm).at(-1)?.outcome,tr=document.createElement('tr');for(let t of [arm,r?(r.decision?.choice||'INVALID'):'Pending',r?(r.valid?(r.evaluation.acceptable_decision?'Acceptable':'Adverse'):'Invalid'):'Pending']){let td=document.createElement('td');td.textContent=t;tr.append(td)}$('decisions').append(tr)}}$('case').onchange=()=>{stop();$('scrub').value=0;render()};$('scrub').oninput=()=>{stop();render()};$('reset').onclick=()=>{stop();$('scrub').value=0;render()};$('play').onclick=()=>{if(timer){stop();return}$('play').textContent='Pause';timer=setInterval(()=>{if(+$('scrub').value>=+$('scrub').max){stop();return}$('scrub').value=+$('scrub').value+1;render()},700)};render();</script></body></html>'''
Path(a.out).write_text(template.replace('__DATA__',data));print('measured replay cases',len(cases))
